import { SITE_NAME, SITE_URL } from "@/lib/content/marketing";

/**
 * The branded share image generated by app/opengraph-image.tsx. Pages that define
 * their own `openGraph` replace the inherited image, so they must list it explicitly.
 */
export const DEFAULT_OG_IMAGES = [
  {
    url: "/opengraph-image",
    width: 1200,
    height: 630,
    alt: "MedicoreERP — Hospital Management System Software",
  },
];

export function absoluteUrl(path = "") {
  if (!path) return SITE_URL;
  return path.startsWith("http") ? path : `${SITE_URL}${path.startsWith("/") ? path : `/${path}`}`;
}

/**
 * Real business details for structured data. Fill these in with the exact
 * address and profile URLs used on Google Business Profile — empty values are
 * left out of the schema rather than published as placeholders.
 */
export const ORG_PROFILE = {
  address: {
    streetAddress: "504 Tasula Residency, Road No. 2B, Ayyappa Society, Madhapur",
    addressLocality: "Hyderabad",
    addressRegion: "Telangana",
    postalCode: "500081",
    addressCountry: "IN",
  },
};

/** One-line office address for display, e.g. in the footer and on the contact page. */
export const OFFICE_ADDRESS = `${ORG_PROFILE.address.streetAddress}, ${ORG_PROFILE.address.addressLocality}, ${ORG_PROFILE.address.addressRegion} ${ORG_PROFILE.address.postalCode}`;

/**
 * Other ways people write the brand. Google uses WebSite/Organization
 * alternateName to recognise brand searches such as "medicore erp".
 */
export const BRAND_ALTERNATE_NAMES = ["MediCoreERP", "Medicore ERP", "MediCore ERP", "medicoreerp"];

/** Office map pin, from the location shared by the owner (Madhapur, Hyderabad). */
export const OFFICE_GEO = { latitude: 17.445256, longitude: 78.391354 };

/**
 * Google Maps link to the exact office pin. When the Google Business Profile is
 * live, replace this with its place link (google.com/maps/place/MedicoreERP/...)
 * and add that link to the Organization sameAs.
 */
export const OFFICE_MAP_URL = `https://www.google.com/maps/search/?api=1&query=${OFFICE_GEO.latitude},${OFFICE_GEO.longitude}`;

/**
 * Official social profiles. Used for the footer icons and the Organization
 * `sameAs` list. Add Instagram, Facebook, YouTube, X or Google Business Profile here.
 */
export const SOCIAL_PROFILES: { network: "LinkedIn" | "Instagram" | "Facebook" | "YouTube" | "X"; url: string }[] = [
  { network: "LinkedIn", url: "https://www.linkedin.com/company/medicore-erp/" },
  { network: "Instagram", url: "https://www.instagram.com/medicoreerp/" },
  { network: "Facebook", url: "https://www.facebook.com/people/Medicoreerp/61596208606847/" },
];

function orgAddress() {
  const a = ORG_PROFILE.address;
  if (!a.streetAddress) return undefined;
  return { "@type": "PostalAddress", ...a };
}

function orgLocation() {
  const address = orgAddress();
  if (!address) return undefined;
  return {
    "@type": "Place",
    name: "MedicoreERP office",
    address,
    geo: { "@type": "GeoCoordinates", ...OFFICE_GEO },
    hasMap: OFFICE_MAP_URL,
  };
}

/** Site-wide schema graph for the document head. */
