export function breadcrumbJsonLd(items: { name: string; path: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: items.map((item, index) => ({
      "@type": "ListItem",
      position: index + 1,
      name: item.name,
      item: absoluteUrl(item.path),
    })),
  };
}

export function articleJsonLd(input: {
  title: string;
  description: string;
  path: string;
  date: string;
  author: string;
  image?: string;
  dateModified?: string;
  keywords?: string[];
  wordCount?: number;
  section?: string;
}) {
  const organizationAuthor = input.author.startsWith(SITE_NAME);
  return {
    "@context": "https://schema.org",
    "@type": "BlogPosting",
    headline: input.title,
    description: input.description,
    datePublished: input.date,
    dateModified: input.dateModified ?? input.date,
    author: organizationAuthor
      ? { "@type": "Organization", name: input.author, url: absoluteUrl("/company/about") }
      : { "@type": "Person", name: input.author },
    image: input.image,
    keywords: input.keywords?.join(", "),
    wordCount: input.wordCount,
    articleSection: input.section,
    inLanguage: "en-IN",
    mainEntityOfPage: absoluteUrl(input.path),
    publisher: {
      "@type": "Organization",
      "@id": `${SITE_URL}/#organization`,
      name: SITE_NAME,
      url: SITE_URL,
      logo: { "@type": "ImageObject", url: `${SITE_URL}/icon.png` },
    },
  };
}

export function faqJsonLd(faqs: { q: string; a: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: faqs.map((f) => ({
      "@type": "Question",
      name: f.q,
      acceptedAnswer: { "@type": "Answer", text: f.a },
    })),
  };
}

export function jobPostingJsonLd(input: {
  title: string;
  description: string;
  location: string;
  path: string;
  employmentType: string;
}) {
  return {
    "@context": "https://schema.org",
    "@type": "JobPosting",
    title: input.title,
    description: input.description,
    hiringOrganization: { "@type": "Organization", name: SITE_NAME, sameAs: SITE_URL },
    jobLocation: {
      "@type": "Place",
      address: { "@type": "PostalAddress", addressLocality: input.location },
    },
    employmentType: input.employmentType.toUpperCase().replace("-", "_"),
    url: absoluteUrl(input.path),
  };
}

export function definedTermJsonLd(input: { term: string; definition: string; path: string }) {
  return {
    "@context": "https://schema.org",
    "@type": "DefinedTerm",
    name: input.term,
    description: input.definition,
    url: absoluteUrl(input.path),
    inDefinedTermSet: absoluteUrl("/resources/glossary"),
  };
}

/** Serialize JSON-LD for a <script type="application/ld+json"> tag. */
export function jsonLdScript(data: unknown) {
  return JSON.stringify(data);
}
